#!/usr/bin/env python3
import sys


def main():
    flags = set()
    file_arg = None

    args = sys.argv[1:]
    i = 0
    while i < len(args):
        arg = args[i]
        if arg.startswith('-') and not arg.lstrip('-').isdigit():
            for ch in arg[1:]:
                if ch == 'l':
                    flags.add('l')
                elif ch == 'w':
                    flags.add('w')
                elif ch == 'c':
                    flags.add('c')
        else:
            file_arg = arg
        i += 1

    if not flags:
        flags = {'l', 'w', 'c'}

    if file_arg is None or file_arg == '-':
        data = sys.stdin.buffer.read()
    else:
        with open(file_arg, 'rb') as f:
            data = f.read()

    lines = data.count(b'\n')
    # If there's content but no trailing newline, count that last partial line too
    if data and not data.endswith(b'\n'):
        lines += 1
    words = len(data.split())
    chars = len(data)

    order = [('l', 'lines'), ('w', 'words'), ('c', 'chars')]
    results = []
    for flag_key, _ in order:
        if flag_key in flags:
            if flag_key == 'l':
                results.append(str(lines))
            elif flag_key == 'w':
                results.append(str(words))
            elif flag_key == 'c':
                results.append(str(chars))

    print(' '.join(results))


if __name__ == '__main__':
    main()
